// Baseline adapters retain the byte operations of the reviewed receive methods;
// socket/session access is replaced by the same injected producer contract.
fn read_owned_chunk(reader: &mut impl embedded_io::Read, len: usize)
 -> Result<Vec<u8>, catten_services::tls_client::StreamError> {
 use catten_services::tls_client::StreamError;
 let mut bytes = vec![0; len];
 let len = reader.read(&mut bytes).map_err(|_| StreamError)?;
 if len == 0 { return Err(StreamError); }
 bytes.truncate(len); Ok(bytes)
}
struct FrameReceiver { received: Vec<u8> }
impl FrameReceiver {
 fn new() -> Self { Self { received: Vec::new() } }
 fn reset(&mut self) { self.received.clear(); }
 fn read_frame<E>(&mut self, mut receive: impl FnMut() -> Result<Zeroizing<Vec<u8>>, E>)
  -> Result<Vec<u8>, ReceiveError<E>> {
  let result = self.read_inner(&mut receive);
  if result.is_err() { self.received.clear(); }
  result
 }
 fn read_inner<E>(&mut self, receive: &mut impl FnMut() -> Result<Zeroizing<Vec<u8>>, E>)
  -> Result<Vec<u8>, ReceiveError<E>> {
  loop {
   if self.received.len() >= 4 {
    let payload = i32::from_be_bytes(self.received[..4].try_into().unwrap());
    if payload < 4 || payload as usize > wire::MAX_FRAME_LEN {
     return Err(ReceiveError::Protocol(wire::Error::Invalid));
    }
    let len = payload as usize + 4;
    if self.received.len() >= len {
     let rest = self.received.split_off(len);
     return Ok(core::mem::replace(&mut self.received, rest));
    }
   }
   self.received.extend_from_slice(&receive().map_err(ReceiveError::Transport)?);
   if self.received.len() > wire::MAX_FRAME_LEN + 4 { return Err(ReceiveError::ChunkTooLarge); }
  }
 }
}

