pub fn read(&mut self, buf: &mut [u8]) -> Result<usize, TlsError> {
    if buf.is_empty() {
        return Ok(0);
    }
    let mut buffer = self.read_buffered()?;

    let len = buffer.pop_into(buf);
    trace!("Copied {} bytes", len);

    Ok(len)
}
